-- LEARN(sql.indexes.stats-pagination): plans are only as good as the row estimates behind them.
CREATE TABLE addresses (id int PRIMARY KEY, city text NOT NULL, district text NOT NULL);
-- Ten districts in five cities: each district belongs to exactly one city.
INSERT INTO addresses
SELECT g, d.city, d.district
FROM generate_series(1, 20000) AS g
JOIN (VALUES (0, 'İstanbul', 'Kadıköy'), (1, 'İstanbul', 'Beşiktaş'),
             (2, 'Ankara', 'Çankaya'),   (3, 'Ankara', 'Keçiören'),
             (4, 'İzmir', 'Konak'),      (5, 'İzmir', 'Bornova'),
             (6, 'Bursa', 'Nilüfer'),    (7, 'Bursa', 'Osmangazi'),
             (8, 'Antalya', 'Muratpaşa'), (9, 'Antalya', 'Konyaaltı'))
  AS d (k, city, district) ON d.k = g % 10;
ANALYZE addresses;

-- The planner's row estimate next to the real count. The condition is pasted
-- into the SQL text: fine for a lesson helper, never for user input.
CREATE FUNCTION estimate_vs_actual(cond text, OUT estimated bigint, OUT actual bigint)
LANGUAGE plpgsql AS $$
DECLARE plan json;
BEGIN
  EXECUTE 'EXPLAIN (FORMAT JSON) SELECT * FROM addresses WHERE ' || cond INTO plan;
  estimated := (plan -> 0 -> 'Plan' ->> 'Plan Rows')::bigint;
  EXECUTE 'SELECT count(*) FROM addresses WHERE ' || cond INTO actual;
END $$;

-- Each condition alone is estimated exactly; together they are multiplied.
SELECT c AS condition, e.estimated, e.actual
FROM unnest(ARRAY[$$city = 'İstanbul'$$, $$district = 'Kadıköy'$$,
                  $$city = 'İstanbul' AND district = 'Kadıköy'$$]) AS c,
     LATERAL estimate_vs_actual(c) AS e;

-- Extended statistics record that district determines city.
CREATE STATISTICS addresses_city_district (dependencies) ON city, district FROM addresses;
ANALYZE addresses;
SELECT * FROM estimate_vs_actual($$city = 'İstanbul' AND district = 'Kadıköy'$$);

-- A bulk import after the last ANALYZE: 5,000 addresses in a city it never saw.
INSERT INTO addresses
SELECT g, 'Eskişehir', 'Tepebaşı' FROM generate_series(20001, 25000) AS g;
SELECT * FROM estimate_vs_actual($$city = 'Eskişehir'$$);
ANALYZE addresses;
SELECT * FROM estimate_vs_actual($$city = 'Eskişehir'$$);

files.examples/02_keyset.sql:
SET LOCAL TimeZone = 'Europe/Istanbul';
CREATE TABLE posts (
  id         bigint PRIMARY KEY,
  created_at timestamptz NOT NULL,
  title      text NOT NULL
);
-- Two posts per minute, so created_at alone has ties; id breaks them.
INSERT INTO posts
SELECT g, timestamptz '2026-01-01 00:00+03' + (g / 2) * interval '1 minute', 'gönderi ' || g
FROM generate_series(1, 20000) AS g;
CREATE INDEX posts_feed ON posts (created_at, id);
ANALYZE posts;

-- Page 1,601 of a newest-first feed, 5 posts per page, by OFFSET...
SELECT id, created_at FROM posts
ORDER BY created_at DESC, id DESC LIMIT 5 OFFSET 8000;

-- ...and by keyset: "older than the last post on the previous page".
SELECT id, created_at FROM posts
WHERE (created_at, id) < ('2026-01-05 04:00+03', 12001)
ORDER BY created_at DESC, id DESC LIMIT 5;

-- Same rows, very different work.
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id, created_at FROM posts
ORDER BY created_at DESC, id DESC LIMIT 5 OFFSET 8000;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id, created_at FROM posts
WHERE (created_at, id) < ('2026-01-05 04:00+03', 12001)
ORDER BY created_at DESC, id DESC LIMIT 5;

-- A reader sees page 1; a new post arrives; the reader asks for page 2.
SELECT id FROM posts ORDER BY created_at DESC, id DESC LIMIT 3;
INSERT INTO posts VALUES (20001, '2026-01-07 22:41+03', 'yeni gönderi');
SELECT id FROM posts ORDER BY created_at DESC, id DESC LIMIT 3 OFFSET 3;
SELECT id FROM posts
WHERE (created_at, id) < ('2026-01-07 22:39+03', 19998)
ORDER BY created_at DESC, id DESC LIMIT 3;

files.examples/03_n_plus_one.sql:
CREATE TABLE posts (id int PRIMARY KEY, title text NOT NULL);
CREATE TABLE comments (
  id      int PRIMARY KEY,
  post_id int NOT NULL REFERENCES posts,
  body    text NOT NULL
);
CREATE INDEX comments_post ON comments (post_id);
INSERT INTO posts SELECT g, 'gönderi ' || g FROM generate_series(1, 1000) AS g;
INSERT INTO comments SELECT g, g % 1000 + 1, 'yorum ' || g FROM generate_series(1, 10000) AS g;
ANALYZE posts, comments;

-- N+1, the way lazy loading sends it: one query for the page...
SELECT id, title FROM posts ORDER BY id LIMIT 3;
-- ...then one more query per row: N more round trips, parses and plans.
SELECT count(*) FROM comments WHERE post_id = 1;
SELECT count(*) FROM comments WHERE post_id = 2;
SELECT count(*) FROM comments WHERE post_id = 3;

-- Batched: one statement for the whole page, the ids as one array parameter.
PREPARE comment_counts(int[]) AS
  SELECT post_id, count(*) AS comments
  FROM comments WHERE post_id = ANY ($1)
  GROUP BY post_id ORDER BY post_id;
EXECUTE comment_counts('{1,2,3}');

-- Or the page and its counts in a single query.
SELECT p.id, p.title, count(c.id) AS comments
FROM (SELECT id, title FROM posts ORDER BY id LIMIT 3) AS p
LEFT JOIN comments c ON c.post_id = p.id
GROUP BY p.id, p.title
ORDER BY p.id;

-- The per-row shape inside one statement: a SubPlan that runs once per row.
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT p.id, (SELECT count(*) FROM comments c WHERE c.post_id = p.id) AS comments
FROM posts p ORDER BY p.id LIMIT 3;
